<template>
<view class="page">
  <animated-loading v-if="loading" text="正在生成本关题目..."></animated-loading>
  <template v-else-if="!finished&&current">
    <view class="head"><text class="eyebrow">第 {{ level.levelNo }} 关</text><text class="title">{{ level.title }}</text><view class="progress"><view :style="{width:progress+'%'}"></view></view><view class="meta"><text>{{ index+1 }}/{{ questions.length }}</text><text>答对 {{ correctCount }} 题</text></view></view>
    <view class="card"><text class="type">{{ typeName }}</text><text class="prompt">{{ current.prompt }}</text><text v-if="current.translation&&current.type!=='word'" class="translation">{{ current.translation }}</text><view v-if="current.audioText" class="play" @click="playAudio">🔊 播放发音</view><view class="options"><view v-for="option in current.options" :key="option" class="option" :class="optionClass(option)" @click="choose(option)"><text>{{ option }}</text></view></view><view v-if="!answered && hintBalance>0 && !hintUsed" class="hint-area"><view class="hint-btn" @click="useHint">💡 使用提示卡（剩 {{ hintBalance }} 张）</view><text class="hint-desc">点击后排除两个错误选项，提高答对概率</text></view><view v-if="!answered && hintUsed" class="hint-tip">✅ 已使用提示卡：两个错误选项已排除</view><view v-if="answered" class="feedback" :class="{ right: isCorrect, wrong: !isCorrect }"><text class="feedback-title">{{ isCorrect ? '回答正确' : '回答错误' }}</text><text>{{ current.explanation }}</text></view><view v-if="answered && !isCorrect" class="next-question" @click="next">下一题</view></view>
  </template>
  <view v-else-if="finished" class="result-card"><view class="result-icon">{{ result.passed ? '🎉' : '🧩' }}</view><text class="result-title">{{ result.passed ? '闯关成功' : '还差一点' }}</text><text class="score">{{ result.score }}<text>分</text></text><text class="result-desc">答对 {{ result.correct }}/{{ result.total }} 题 · 通关要求 {{ passScore }} 分</text><text v-if="result.shieldUsed" class="shield-tip">🛡️ 免扣星已生效，本次闯关成功</text><view class="stars">{{ resultStars }}</view><view v-if="result.wrong&&result.wrong.length" class="weak"><text class="weak-title">本轮薄弱内容</text><text v-for="item in result.wrong.slice(0,3)" :key="item.id">• {{ item.prompt }}</text></view><button v-if="result.passed&&result.next" class="primary" @click="goNext">继续下一关</button><button v-else class="primary" @click="restart">重新挑战</button><button class="secondary" @click="goMap">返回成长地图</button></view>
  <view v-if="celebration" class="celebrate-mask" @click="backToMap">
    <view class="fireworks">
      <view v-for="(spark, i) in fireworks" :key="i" class="spark" :style="sparkStyle(spark)"></view>
    </view>
    <view class="celebrate-card">
      <view class="celebrate-ring"></view>
      <text class="celebrate-icon">🎉</text>
      <text class="celebrate-title">场景通关！</text>
      <text class="celebrate-sub">学习地图已解锁新的模块</text>
      <text class="celebrate-name">{{ celebrationModule || '前往地图查看' }}</text>
      <text class="celebrate-hint">点击返回学习地图</text>
    </view>
  </view>
<view v-if="showFailModal" class="fail-overlay"><view class="fail-card"><text class="fail-icon">🧩</text><text class="fail-title">未通关</text><text class="fail-desc">答对 {{ result.correct }}/{{ result.total }} 题 · 得分 {{ result.score }} 分，还差一点就过关了</text><view class="fail-actions"><view class="fail-btn back" @click="backToLevels">返回关卡</view><view class="fail-btn retry" @click="retryLevel">重新闯关</view></view></view></view><AchievementUnlockNotifier />
</view>
</template>
<script>
import { request, getSettings, getAchievementRewards, useAchievementReward } from '@/utils/api.js';
import { isFirstLoad } from '@/utils/first-load.js';
import { playTts, clearTtsQueue } from '@/utils/tts-player.js';
import { playAnswerFeedback } from '@/utils/answer-feedback.js';
export default{data(){const firstLoad=isFirstLoad('pages/adventure/practice');return{levelId:'',firstLoad,loading:firstLoad,level:{},questions:[],index:0,answered:false,selected:'',isCorrect:false,answers:[],finished:false,result:{},passScore:80,audio:null,advanceTimer:null,audioTimer:null,audioRequestId:0,autoPlay:false,accent:0,celebration:false,celebrationModule:'',fireworks:[],unlockAudio:null,hintBalance:0,hintUsed:false,dimmedOptions:[],shieldUsed:false,showFailModal:false,failAudio:null}},computed:{current(){return this.questions[this.index]},resultStars(){if(!this.result.passed)return '☆☆☆';return '★'.repeat(this.result.stars||0)+'☆'.repeat(3-(this.result.stars||0))},progress(){return this.questions.length?this.index*100/this.questions.length:0},correctCount(){return this.answers.filter(item=>item.correct).length},typeName(){return this.current?.type==='grammar'?'语法应用':(this.current?.type==='phonetic'?'音标训练':(this.current?.type==='listen'?'听音辨义':'单词理解'))}},onLoad(q){this.levelId=String(q.id||'');this.load()},onUnload(){clearTtsQueue();if(this.advanceTimer)clearTimeout(this.advanceTimer);if(this.audioTimer)clearTimeout(this.audioTimer);this.clearUnlockAudio();this.clearFailAudio()},methods:{async load(){if(this.firstLoad){this.loading=true;this.firstLoad=false}try{const [data,settings]=await Promise.all([request('/adventure-course/level/'+this.levelId+'/questions'),getSettings()]);this.autoPlay=Boolean(Number(settings?.auto_play||0));this.accent=Number(settings?.accent||0);this.level=data.level;this.questions=data.questions||[];this.passScore=data.passScore;this.index=0;this.answers=[];this.finished=false;this.answered=false;this.hintUsed=false;this.dimmedOptions=[];this.scheduleAutoPlay();this.loadRewards()}catch(e){uni.showModal({title:'无法开始关卡',content:e.message||'题目加载失败',showCancel:false,success:()=>uni.navigateBack()})}finally{this.loading=false}},choose(option){if(this.answered||this.dimmedOptions.includes(option))return;this.selected=option;this.answered=true;this.isCorrect=option===this.current.answer;playAnswerFeedback(this.isCorrect);this.answers.push({id:this.current.id,type:this.current.type,prompt:this.current.prompt,userAnswer:option,answer:this.current.answer,explanation:this.current.explanation,correct:this.isCorrect});if(this.advanceTimer)clearTimeout(this.advanceTimer);if(this.isCorrect){this.advanceTimer=setTimeout(()=>{this.advanceTimer=null;this.next()},350)}},optionClass(option){if(this.dimmedOptions.includes(option))return 'dim';if(!this.answered)return '';if(option===this.current.answer)return 'correct';if(option===this.selected)return 'wrong';return 'dim'},async next(){if(!this.answered)return;if(this.index+1<this.questions.length){this.index++;this.answered=false;this.selected='';this.isCorrect=false;this.hintUsed=false;this.dimmedOptions=[];this.scheduleAutoPlay();return}uni.showLoading({title:'正在结算'});try{this.result=await request('/adventure-course/level/'+this.levelId+'/submit','POST',{answers:this.answers});this.shieldUsed=Boolean(this.result?.shieldUsed);if(this.result?.passed){uni.setStorageSync('adventureLevelPassed',{levelKey:this.levelId,moduleKey:this.result?.moduleKey||'',nextLevelKey:this.result?.next||'',moduleCompleted:Boolean(this.result?.moduleCompleted),score:Number(this.result?.score||0),correct:Number(this.result?.correct||0),total:Number(this.result?.total||0)});this.finished=true;setTimeout(()=>uni.navigateBack(),300)}else{this.playFailAudio();this.finished=false;this.showFailModal=true}}catch(e){uni.showToast({title:e.message||'结算失败',icon:'none'})}finally{uni.hideLoading()}},loadRewards(){try{getAchievementRewards().then(r=>{this.hintBalance=Number(r?.hint_card||0)}).catch(()=>{})}catch(e){}},useHint(){if(this.hintUsed||this.answered||this.hintBalance<=0)return;useAchievementReward('hint_card',1).then(()=>{this.hintUsed=true;this.hintBalance=Math.max(0,this.hintBalance-1);const wrong=this.current.options.filter(o=>o!==this.current.answer);const dims=[];const copy=[...wrong];for(let i=0;i<2&&copy.length;i++){dims.push(copy.splice(Math.floor(Math.random()*copy.length),1)[0])}this.dimmedOptions=dims}).catch(e=>uni.showToast({title:e.message||'提示卡使用失败',icon:'none'}))},playFailAudio(){this.clearFailAudio();try{const audio=uni.createInnerAudioContext();audio.autoplay=false;audio.volume=1;audio.src='/static/audio/level-fail.mp3';audio.onCanplay(()=>audio.play());audio.onError(()=>{});this.failAudio=audio}catch(e){}},clearFailAudio(){const audio=this.failAudio;this.failAudio=null;if(audio){try{audio.stop();audio.destroy()}catch(e){}}},retryLevel(){this.clearFailAudio();this.showFailModal=false;this.load()},backToLevels(){this.clearFailAudio();this.showFailModal=false;uni.navigateBack()},scheduleAutoPlay(){if(this.audioTimer)clearTimeout(this.audioTimer);if(!this.autoPlay||!this.current?.audioText)return;this.audioTimer=setTimeout(()=>{this.audioTimer=null;this.playAudio()},350)},playAudio(){if(!this.current?.audioText)return;playTts(this.current.audioText,3).catch(error=>{console.error('闯关语音播放失败:',error);uni.showToast({title:error?.message||'播放失败，请重试',icon:'none'})})},restart(){this.load()},goNext(){uni.redirectTo({url:'/pages/adventure/practice?id='+this.result.next})},goMap(){uni.redirectTo({url:'/pages/adventure/module?key='+this.result.moduleKey})},
async prepareUnlockCelebration(){this.celebration=true;this.buildFireworks();this.playUnlockFanfare();try{const data=await request('/adventure-course/modules');const modules=data?.modules||[];const next=modules.find(item=>item.unlocked&&!item.completed);if(next)this.celebrationModule=next.world+' · '+next.stage}catch(e){}},
buildFireworks(){const colors=['#ffd93d','#ff6b6b','#4ecdc4','#ffe66d','#ff9f43','#6c5ce7','#00cec9','#fd79a8'];const sparks=[];for(let b=0;b<4;b++){const fx=12+(b*23+8)%76;const fy=18+(b*17+10)%55;const color=colors[(b*3)%colors.length];for(let i=0;i<10;i++){const angle=(i/10)*Math.PI*2;const dist=110+(i%4)*40;sparks.push({left:fx+'%',top:fy+'%',dx:Math.round(Math.cos(angle)*dist)+'rpx',dy:Math.round(Math.sin(angle)*dist)+'rpx',color:color,delay:((b*0.45)+i*0.015).toFixed(2)+'s',dur:(0.9+(i%3)*0.15).toFixed(2)+'s'})}}this.fireworks=sparks},
sparkStyle(spark){return 'left:'+spark.left+';top:'+spark.top+';--dx:'+spark.dx+';--dy:'+spark.dy+';background:'+spark.color+';box-shadow:0 0 14rpx 5rpx '+spark.color+';animation-delay:'+spark.delay+';animation-duration:'+spark.dur},
playUnlockFanfare(){this.clearUnlockAudio();try{const audio=uni.createInnerAudioContext();audio.autoplay=false;audio.volume=1;audio.src='/static/audio/fanfare-unlock.mp3';audio.onCanplay(()=>{audio.play()});audio.onEnded(()=>this.clearUnlockAudio());audio.onError(()=>this.clearUnlockAudio());this.unlockAudio=audio}catch(e){}},
clearUnlockAudio(){const audio=this.unlockAudio;this.unlockAudio=null;if(audio){try{audio.stop();audio.destroy()}catch(e){}}},
backToMap(){this.celebration=false;this.fireworks=[];this.clearUnlockAudio();const pages=getCurrentPages();if(pages.length>=3){uni.navigateBack({delta:2})}else{uni.reLaunch({url:'/pages/adventure/index'})}}
}}
</script>
<style>
.page{box-sizing:border-box;min-height:100vh;padding:24rpx 22rpx 50rpx;background:linear-gradient(180deg,#edf5f6,#f7f5f0 430rpx)}.head{text-align:center}.eyebrow{font-size:21rpx;font-weight:800;color:#0d9488}.title{display:block;margin-top:5rpx;font-size:40rpx;font-weight:900;color:#1f3a5f}.progress{height:10rpx;margin-top:23rpx;border-radius:8rpx;background:#dfe7ea;overflow:hidden}.progress view{height:100%;border-radius:8rpx;background:#159e92}.meta{display:flex;justify-content:space-between;margin-top:9rpx;font-size:21rpx;color:#7f8d98}.card{margin-top:24rpx;padding:29rpx 24rpx;border-radius:25rpx;background:#fff;box-shadow:0 8rpx 25rpx rgba(31,58,95,.08)}.type{font-size:21rpx;font-weight:800;color:#0d9488}.prompt{display:block;margin-top:22rpx;font-size:34rpx;font-weight:800;line-height:1.5;color:#213f61}.translation{display:block;margin-top:10rpx;padding:13rpx 16rpx;border-radius:12rpx;background:#f3f7f8;font-size:22rpx;color:#73838e}.play{display:inline-block;margin-top:18rpx;padding:13rpx 20rpx;border-radius:25rpx;background:#e5f6f2;color:#0d9488;font-size:22rpx}.options{margin-top:24rpx}.option{margin-top:13rpx;padding:23rpx 20rpx;border:2rpx solid #e6ebee;border-radius:16rpx;background:#fff;font-size:27rpx;color:#344c61}.option.correct{border-color:#40b982;background:#edfaf3;color:#17865d}.option.wrong{border-color:#e36b64;background:#fff1ef;color:#c94e47}.option.dim{opacity:.55}.feedback{margin-top:20rpx;padding:18rpx;border-radius:15rpx;font-size:22rpx;line-height:1.5}.feedback text{display:block}.feedback-title{margin-bottom:4rpx;font-size:25rpx;font-weight:900}.feedback.right{background:#edf9f4;color:#16845f}.feedback.wrong{background:#fff2ef;color:#c9534c}.next,.primary,.secondary{height:82rpx;line-height:82rpx;margin-top:22rpx;border:0;border-radius:17rpx;background:#1f3a5f;color:#fff;font-size:28rpx;font-weight:800}.next:after,.primary:after,.secondary:after{border:0}.next[disabled]{background:#dce2e7;color:#96a0a9}.state{padding:180rpx 0;text-align:center;color:#7f8d98}.result-card{margin-top:35rpx;padding:42rpx 28rpx;border-radius:28rpx;background:#fff;text-align:center;box-shadow:0 9rpx 28rpx rgba(31,58,95,.1)}.result-icon{font-size:73rpx}.result-title{display:block;margin-top:11rpx;font-size:39rpx;font-weight:900;color:#213f61}.score{display:block;margin-top:15rpx;font-size:70rpx;font-weight:900;color:#0d9488}.score text{font-size:25rpx}.result-desc{display:block;margin-top:5rpx;font-size:22rpx;color:#81909b}.stars{margin-top:17rpx;font-size:42rpx;letter-spacing:7rpx;color:#d6a53a}.weak{margin-top:25rpx;padding:20rpx;border-radius:18rpx;background:#fff5f2;text-align:left;color:#7b5a54}.weak text{display:block;margin-top:7rpx;font-size:21rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.weak-title{font-size:25rpx!important;font-weight:900;color:#c7544b}.secondary{margin-top:13rpx;background:#edf2f5;color:#526a7d}
.celebrate-mask{position:fixed;left:0;top:0;right:0;bottom:0;z-index:99;display:flex;align-items:center;justify-content:center;background:rgba(15,25,45,.6);animation:maskFade .35s ease both}.fireworks{position:absolute;left:0;top:0;right:0;bottom:0;overflow:hidden;pointer-events:none}.spark{position:absolute;width:10rpx;height:10rpx;border-radius:50%;opacity:0;animation-name:sparkBurst;animation-timing-function:ease-out;animation-fill-mode:forwards}.celebrate-card{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;width:580rpx;padding:54rpx 34rpx 42rpx;border-radius:38rpx;background:linear-gradient(165deg,#fffdf4,#fff);box-shadow:0 20rpx 70rpx rgba(0,0,0,.4),0 0 0 6rpx rgba(255,214,102,.6);animation:cardPop .6s cubic-bezier(.2,1.7,.35,1) both}.celebrate-ring{position:absolute;top:50%;left:50%;width:340rpx;height:340rpx;margin:-170rpx 0 0 -170rpx;border:4rpx dashed rgba(255,193,7,.8);border-radius:50%;animation:ringSpin 6s linear infinite}.celebrate-ring:after{content:"";position:absolute;top:18rpx;right:18rpx;bottom:18rpx;left:18rpx;border:2rpx solid rgba(255,193,7,.45);border-radius:50%;animation:ringSpin 9s linear infinite reverse}.celebrate-icon{position:relative;z-index:1;font-size:100rpx;line-height:1;animation:iconBounce 1s ease-in-out infinite}.celebrate-title{position:relative;z-index:1;margin-top:24rpx;font-size:46rpx;font-weight:900;color:#1f3a5f}.celebrate-sub{position:relative;z-index:1;margin-top:10rpx;font-size:24rpx;color:#7d8994}.celebrate-name{margin-top:26rpx;padding:16rpx 34rpx;border-radius:32rpx;background:linear-gradient(90deg,#ffd54a,#ff9f43);color:#5b3a00;font-size:30rpx;font-weight:800;box-shadow:0 10rpx 22rpx rgba(255,159,67,.4)}.celebrate-hint{position:relative;z-index:1;margin-top:28rpx;font-size:20rpx;color:#a5aeb8}@keyframes maskFade{from{opacity:0}to{opacity:1}}@keyframes cardPop{0%{transform:scale(.5);opacity:0}100%{transform:scale(1);opacity:1}}@keyframes ringSpin{from{transform:rotate(0)}to{transform:rotate(360deg)}}@keyframes iconBounce{0%,100%{transform:translateY(0) scale(1)}30%{transform:translateY(-28rpx) scale(1.12)}55%{transform:translateY(0) scale(.96)}75%{transform:translateY(-12rpx) scale(1.05)}}@keyframes sparkBurst{0%{transform:translate(0,0) scale(1);opacity:1}100%{transform:translate(var(--dx),var(--dy)) scale(.15);opacity:0}}
.next-question{height:82rpx;line-height:82rpx;margin-top:22rpx;border-radius:17rpx;background:#1f3a5f;color:#fff;font-size:28rpx;font-weight:800;text-align:center}
.shield-tip{display:block;margin-top:12rpx;color:#c88a1d;font-size:22rpx;font-weight:800}
.hint-area{display:flex;flex-direction:column;align-items:flex-start;margin-top:20rpx}.hint-btn{display:inline-block;padding:13rpx 24rpx;border-radius:24rpx;background:linear-gradient(135deg,#ffe9a8,#ffd76a);color:#8a5a00;font-size:23rpx;font-weight:800;box-shadow:0 6rpx 14rpx rgba(214,150,30,.18)}.hint-desc{display:block;margin-top:8rpx;font-size:20rpx;color:#8d99a3}.hint-tip{display:inline-block;margin-top:20rpx;padding:13rpx 24rpx;border-radius:24rpx;background:#eef6f3;color:#0d8c81;font-size:22rpx;font-weight:700}
.fail-overlay{position:fixed;left:0;top:0;right:0;bottom:0;z-index:98;display:flex;align-items:center;justify-content:center;background:rgba(15,25,45,.55);animation:maskFade .3s ease both}.fail-card{display:flex;flex-direction:column;align-items:center;width:560rpx;padding:50rpx 34rpx 40rpx;border-radius:34rpx;background:linear-gradient(165deg,#fff,#fdf1ef);box-shadow:0 20rpx 70rpx rgba(0,0,0,.35),0 0 0 6rpx rgba(227,107,100,.45);animation:cardPop .45s cubic-bezier(.2,1.4,.4,1) both}.fail-icon{font-size:84rpx;line-height:1}.fail-title{margin-top:20rpx;font-size:42rpx;font-weight:900;color:#c9534c}.fail-desc{margin-top:12rpx;font-size:24rpx;line-height:1.6;color:#7d8994;text-align:center}.fail-actions{display:flex;gap:18rpx;margin-top:36rpx;width:100%}.fail-btn{flex:1;height:84rpx;line-height:84rpx;border-radius:42rpx;font-size:28rpx;font-weight:800;text-align:center}.fail-btn.back{background:#edf2f5;color:#526a7d}.fail-btn.retry{background:linear-gradient(135deg,#e36b64,#f08a5a);color:#fff;box-shadow:0 10rpx 22rpx rgba(227,107,100,.3)}
</style>
